module mmcm
   (clk_out1,
    clk_out2,
    resetn,
    locked,
    clk_in1);
  output clk_out1;
  output clk_out2;
  input resetn;
  output locked;
  input clk_in1;

  wire clk_in1;
  wire clk_out2;
  wire resetn;
  wire NLW_inst_clk_out1_UNCONNECTED;
  wire NLW_inst_locked_UNCONNECTED;

  mmcm_clk_wiz inst
       (.clk_in1(clk_in1),
        .clk_out1(NLW_inst_clk_out1_UNCONNECTED),
        .clk_out2(clk_out2),
        .locked(NLW_inst_locked_UNCONNECTED),
        .resetn(resetn));
endmodule

